{"command": "create", "file_text": "<template>\n  <div>\n    <h1>Profile Selling</h1>\n    <ul>\n      <li v-for=\"item in soldItems\" :key=\"item.id\">\n        {{ item.name }} ({{ item.reviewCount }})\n      </li>\n    </ul>\n  </div>\n</template>\n\n<script>\nexport default {\n  data() {\n    return {\n      soldItems: []\n    }\n  },\n  mounted() {\n    this.fetchSoldItems()\n  },\n  methods: {\n    fetchSoldItems() {\n      // Call API to fetch sold items and review counts\n      this.$axios.get('/api/sold-items').then(response => {\n        this.soldItems = response.data\n      })\n    }\n  }\n}\n</script>", "path": "src/views/ProfileSelling.vue"}